/**
 * Represents a single error evaluation condition for an action.
 *
 * Each condition defines a rule that evaluates at runtime to determine
 * the action's status. Conditions are evaluated in order — the first
 * matching condition's status is applied.
 */
export interface ErrorEvaluationCondition {
    /** Display label for the condition (visible in Flow Designer). */
    label: string;
    /**
     * Query-style condition string. May include datapill references
     * via template literals with `wfa.dataPill()`.
     *
     * @example
     * ```typescript
     * condition: `${wfa.dataPill(step1.__step_status__.code, 'integer')}=500`
     * ```
     */
    condition: string;
    /** The status to set when this condition matches. */
    status: {
        /** Status code (integer). Can be a number or a template expression with datapills. */
        code: number | string;
        /** Status message. Can be a string or a template expression with datapills. */
        message: string;
    };
    /** When true, the action does not treat this condition as an error. Defaults to false. */
    dontTreatAsError?: boolean;
}
/**
 * Defines error evaluation conditions within an action body.
 *
 * Error evaluation allows an action to conditionally set its status
 * based on step outputs and input values. This maps to
 * `sys_hub_action_status_metadata` and `sys_hub_status_condition`
 * records in the platform.
 *
 * @param _conditions - Array of error evaluation conditions, evaluated in order.
 * @returns A marker type — this function is erased at runtime.
 *
 * @example
 * ```typescript
 * Action(
 *     { ... },
 *     (params) => {
 *         const step1 = wfa.actionStep(actionStep.createRecord, ...)
 *
 *         wfa.errorEvaluation([
 *             {
 *                 label: 'success check',
 *                 condition: `${wfa.dataPill(step1.__step_status__.code, 'integer')}!=500`,
 *                 status: { code: 200, message: 'OK' },
 *                 dontTreatAsError: true,
 *             },
 *         ])
 *     }
 * )
 * ```
 */
export declare function ErrorEvaluation(_conditions: ErrorEvaluationCondition[]): void;
